n = 15
from collections import deque

def find_short_cycles(adj, max_len=7):
    # adj is dict or list
    cycles = []
    for start in range(n):
        # BFS/DFS building paths up to max_len vertices
        # stack entries: (vertex, path)
        stack = [(start, [start])]
        while stack:
            u, path = stack.pop()
            if len(path) > max_len:
                continue
            for w in adj.get(u, []):
                if w == start and len(path) >= 3 and len(path) <= max_len:
                    cycles.append(tuple(path))
                elif w not in path:
                    # To reduce duplicates, enforce ordering: only continue to w > start or
                    # Actually we need to allow w < start if start is smallest in cycle?
                    # Let's just enforce w > path[-2] to avoid backtracking along the edge we came from? Not enough.
                    # Let's canonicalize later.
                    stack.append((w, path + [w]))
    # canonicalize cycles
    def canon(cycle):
        k = len(cycle)
        best = None
        # all rotations
        for i in range(k):
            rot = tuple(cycle[i:] + cycle[:i])
            # reversed
            rev = tuple([rot[0]] + list(rot[:0:-1]))
            if best is None or rot < best:
                best = rot
            if rev < best:
                best = rev
        return best
    seen = set()
    unique = []
    for c in cycles:
        can = canon(c)
        if can not in seen:
            seen.add(can)
            unique.append(can)
    return unique

